45	func TestWriteCommitted_WritesCompactTranscript(t *testing.T) {
46		t.Parallel()
47		repo, _ := setupTestRepo(t)
48		store := NewGitStore(repo, DefaultV1Refs())
49		cpID := id.MustCheckpointID("a1b2c3d4e5f6")
50	
51		err := store.Write(context.Background(), Session{
52			CheckpointID: cpID,
53			SessionID:    "session-001",
54			Strategy:     "manual-commit",
55			Transcript:   redact.AlreadyRedacted(claudeStyleTranscript()),
56			Prompts:      []string{"hello one"},
57			Agent:        agent.AgentTypeClaudeCode,
58			AuthorName:   "Test",
59			AuthorEmail:  "test@test.com",
60		})
61		if err != nil {
62			t.Fatalf("WriteCommitted() error = %v", err)
63		}
64	
65		sessionPath := cpID.Path() + "/0/"
66	
67		// full.jsonl is still written for CLI read paths.
68		if _, ok := readBranchFile(t, store, sessionPath+paths.TranscriptFileName); !ok {
69			t.Error("full.jsonl missing from checkpoint tree")
70		}
71	
72		// transcript.jsonl is written with compact content derived from the
73		// transcript. The compact format itself is covered by transcript/compact;
74		// here we only assert the store persisted non-empty derived content.
75		compactContent, ok := readBranchFile(t, store, sessionPath+paths.CompactTranscriptFileName)
76		if !ok {
77			t.Fatal("transcript.jsonl missing from checkpoint tree")
78		}
79		if !strings.Contains(compactContent, "reply two") {
80			t.Error("compact transcript missing assistant content")
81		}
82	
83		// Root metadata.json still points at full.jsonl via transcript; the compact
84		// transcript is written into the tree (and pushed) and pointed at by
85		// compact_transcript.
86		summary := readSummaryFromBranch(t, repo, cpID)
87		if len(summary.Sessions) != 1 {
88			t.Fatalf("session count = %d, want 1", len(summary.Sessions))
89		}
90		wantTranscript := "/" + sessionPath + paths.TranscriptFileName
91		if summary.Sessions[0].Transcript != wantTranscript {
92			t.Errorf("sessions[0].transcript = %q, want %q", summary.Sessions[0].Transcript, wantTranscript)
93		}
94		wantHash := "/" + sessionPath + paths.ContentHashFileName
95		if summary.Sessions[0].ContentHash != wantHash {
96			t.Errorf("sessions[0].content_hash = %q, want %q", summary.Sessions[0].ContentHash, wantHash)
97		}
98		wantCompact := "/" + sessionPath + paths.CompactTranscriptFileName
99		if summary.Sessions[0].CompactTranscript != wantCompact {
100			t.Errorf("sessions[0].compact_transcript = %q, want %q", summary.Sessions[0].CompactTranscript, wantCompact)
101		}
102	}
