105		t.Parallel()
106		repo, _ := setupTestRepo(t)
107		store := NewGitStore(repo, DefaultV1Refs())
108		cpID := id.MustCheckpointID("b2c3d4e5f6a1")
109	
110		err := store.Write(context.Background(), Session{
111			CheckpointID:              cpID,
112			SessionID:                 "session-001",
113			Strategy:                  "manual-commit",
114			Transcript:                redact.AlreadyRedacted(claudeStyleTranscript()),
115			Agent:                     agent.AgentTypeClaudeCode,
116			CheckpointTranscriptStart: 2,
117			AuthorName:                "Test",
118			AuthorEmail:               "test@test.com",
119		})
120		if err != nil {
121			t.Fatalf("WriteCommitted() error = %v", err)
122		}
123	
124		compactContent, ok := readBranchFile(t, store, cpID.Path()+"/0/"+paths.CompactTranscriptFileName)
125		if !ok {
126			t.Fatal("transcript.jsonl missing from checkpoint tree")
127		}
128		if strings.Contains(compactContent, "hello one") || strings.Contains(compactContent, "reply one") {
129			t.Errorf("compact transcript contains content before checkpoint start:\n%s", compactContent)
130		}
131		if !strings.Contains(compactContent, "hello two") || !strings.Contains(compactContent, "reply two") {
132			t.Errorf("compact transcript missing checkpoint-scoped content:\n%s", compactContent)
133		}
134	}
